# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">BİR SURE ÖĞRENİYORUM: KÂFİRÛN SURESİ (DKAB.7.2.4)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Kâfirûn Suresinin Temel Özellikleri</text>\n  <text x="40" y="98" font-size="11.5" fill="#334155">• Kur\'an-ı Kerim\'in 109. suresidir (6 ayettir).</text>\n  <text x="40" y="122" font-size="11.5" fill="#334155">• Mekke döneminde indirilmiştir (Mekkî suredir).</text>\n  <text x="40" y="146" font-size="11.5" fill="#334155">• Adını 1. ayetteki "el-Kâfirûn" kelimesinden alır.</text>\n  <text x="40" y="170" font-size="11.5" fill="#334155">• Müşriklerin uzlaşma teklifini kesin olarak reddeder.</text>\n  <text x="40" y="194" font-size="11.5" fill="#334155">• "Tevhit ve İhlas Suresi" olarak da anılır.</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Tevhit ile Şirkin Kesin Ayrımı</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Okunuşu (Bismillâhirrahmânirrahîm)</text>\n  <text x="375" y="98" font-size="11" fill="#334155">1. Kul yâ eyyühe\'l-kâfirûn.</text>\n  <text x="375" y="120" font-size="11" fill="#334155">2. Lâ a\'büdü mâ ta\'büdûn.</text>\n  <text x="375" y="142" font-size="11" fill="#334155">3. Ve lâ entüm âbidûne mâ a\'büd.</text>\n  <text x="375" y="164" font-size="11" fill="#334155">4. Ve lâ ene âbidün mâ abedtüm.</text>\n  <text x="375" y="186" font-size="11" fill="#334155">5. Ve lâ entüm âbidûne mâ a\'büd.</text>\n  <text x="375" y="210" font-size="11.5" font-weight="bold" fill="#166534">6. Leküm dînüküm veliye dîn.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KÂFİRÛN SURESİNİN ANLAMI VE TEMEL İLKELERİ</text>\n  <rect x="25" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Surenin Türkçe Anlamı (Meali)</text>\n  <text x="38" y="96" font-size="10.5" fill="#334155">1. De ki: "Ey Kâfirler (inkârcılar)!</text>\n  <text x="38" y="118" font-size="10.5" fill="#334155">2. Ben sizin kulluk ettiklerinize kulluk etmem.</text>\n  <text x="38" y="140" font-size="10.5" fill="#334155">3. Siz de benim kulluk ettiğime kulluk edecek değilsiniz.</text>\n  <text x="38" y="162" font-size="10.5" fill="#334155">4. Ben sizin kulluk ettiklerinize kulluk edecek değilim.</text>\n  <text x="38" y="184" font-size="10.5" fill="#334155">5. Siz de benim kulluk ettiğime kulluk etmezsiniz.</text>\n  <text x="38" y="208" font-size="11" font-weight="bold" fill="#92400e">6. Sizin dininiz size, benim dinim de banadır."</text>\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Suredeki Üç Temel Mesaj</text>\n  <text x="380" y="102" font-size="11.5" font-weight="bold" fill="#9d174d">1. Tevhit İnancında Tavizsizlik:</text>\n  <text x="380" y="122" font-size="11" fill="#334155">İnanç ve ibadette şirkle ortaklık kabul edilemez.</text>\n  <text x="380" y="150" font-size="11.5" font-weight="bold" fill="#9d174d">2. İbadette İhlas ve Samimiyet:</text>\n  <text x="380" y="170" font-size="11" fill="#334155">Kulluk yalnız bir olan Allah\'a (cc) yapılır.</text>\n  <text x="380" y="198" font-size="11.5" font-weight="bold" fill="#9d174d">3. İnanç Özgürlüğü ve Sorumluluk:</text>\n  <text x="380" y="218" font-size="11" fill="#334155">İnanmada zorlama yoktur; herkes kendi seçiminden sorumludur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAC, UMRE VE KURBAN TEMASI BÜTÜNCÜL ÖZET TABLOSU</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Hac İbadeti (Farz)</text>\n  <text x="34" y="98" font-size="11" fill="#334155">• Farzları: İhram, Vakfe, Tavaf</text>\n  <text x="34" y="120" font-size="11" fill="#334155">• Vacip: Sa\'y, Müzdelife, Şeytan taşlama</text>\n  <text x="34" y="142" font-size="11" fill="#334155">• Zaman: Zilhicce (Arefe + Bayram)</text>\n  <text x="34" y="164" font-size="11" fill="#334155">• Ömründe 1 kez (gücü yetene)</text>\n  <text x="125" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">Arafat Vakfesi Haccın Rüknüdür</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Umre İbadeti (Sünnet)</text>\n  <text x="259" y="98" font-size="11" fill="#334155">• Unsurları: İhram + Tavaf + Sa\'y</text>\n  <text x="259" y="120" font-size="11" fill="#334155">• Vakfe, Mina ve Kurban yoktur</text>\n  <text x="259" y="142" font-size="11" fill="#334155">• Kurban Bayramı günleri dışında</text>\n  <text x="259" y="164" font-size="11" fill="#334155">• Yılın her mevsiminde yapılabilir</text>\n  <text x="350" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">Tıraş Olup İhramdan Çıkılır</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Kurban İbadeti (Vacip)</text>\n  <text x="484" y="98" font-size="11" fill="#334155">• Koyun/Keçi: 1 yaş (1 kişi)</text>\n  <text x="484" y="120" font-size="11" fill="#334155">• Sığır/Manda: 2 yaş (1-7 kişi)</text>\n  <text x="484" y="142" font-size="11" fill="#334155">• Deve: 5 yaş (1-7 kişi ortak)</text>\n  <text x="484" y="164" font-size="11" fill="#334155">• Türler: Udhiyye, Akika, Adak, Hedy</text>\n  <text x="575" y="216" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">En\'âm 162 ve Kâfirûn Suresi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
